const WHATSAPP_SECRET_KEYS = [
  "whatsapp_access_token",
  "whatsapp_app_secret",
  "whatsapp_phone_number_id",
  "whatsapp_webhook_verify_token",
  "whatsapp_test_number"
] as const;

export function stripStoredWhatsAppConfiguration(
  settings: Record<string, unknown>
): Record<string, unknown> {
  const sanitized = { ...settings };
  for (const key of WHATSAPP_SECRET_KEYS) {
    delete sanitized[key];
  }
  return sanitized;
}

export function mergeNotificationSettings(
  current: Record<string, unknown>,
  updates: Record<string, unknown>
): Record<string, unknown> {
  return stripStoredWhatsAppConfiguration({
    ...current,
    ...updates
  });
}

src/utils/onboarding.ts:
import { supabase } from '../supabaseClient';
import { trackLifecycleEvent } from '../services/lifecycleTelemetry';
import {
  canAccessApplicationDuringOnboarding,
  getOnboardingDestinationForState,
  hydrateOnboardingState,
  normalizeOnboardingState,
  type OnboardingMode,
  type OnboardingState,
  type RemoteOnboardingProfile,
} from './onboardingState';

export type { OnboardingMode, OnboardingState, OnboardingStatus, OnboardingStep } from './onboardingState';

const ONBOARDING_STORAGE_PREFIX = 'evolucao-clinica:onboarding';

const getStorageKey = (userId: string) => `${ONBOARDING_STORAGE_PREFIX}:${userId}`;

const safeParse = (value: string | null): OnboardingState | null => {
  if (!value) return null;

  try {
    return normalizeOnboardingState(JSON.parse(value) as Partial<OnboardingState>);
  } catch {
    return null;
  }
};

export const getOnboardingState = (userId?: string | null): OnboardingState | null => {
  if (!userId || typeof window === 'undefined') return null;
  return safeParse(window.localStorage.getItem(getStorageKey(userId)));
};

export const ensureOnboardingState = (userId?: string | null): OnboardingState | null => {
  if (!userId || typeof window === 'undefined') return null;

  const current = getOnboardingState(userId);
  if (current) return current;

  const initialState: OnboardingState = {
    step: 'intro',
    status: 'not_started',
    startedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };

  window.localStorage.setItem(getStorageKey(userId), JSON.stringify(initialState));
  return initialState;
};

export const setOnboardingState = (
  userId: string,
  patch: Partial<OnboardingState>
): OnboardingState => {
  const current = ensureOnboardingState(userId) || normalizeOnboardingState(null);
  const stepChanged = Boolean(patch.step && patch.step !== current.step);
  const inferredStatus = patch.status || (
    patch.step === 'complete'
      ? 'completed'
      : stepChanged && patch.step !== 'intro'
        ? 'in_progress'
        : current.status
  );
  const nextState: OnboardingState = {
    ...current,
    ...patch,
    status: inferredStatus,
    updatedAt: new Date().toISOString()
  };

  window.localStorage.setItem(getStorageKey(userId), JSON.stringify(nextState));

  const databasePatch = {
    onboarding_status: nextState.status,
    onboarding_mode: nextState.mode || null,
    onboarding_current_step: nextState.step,
    onboarding_choice_at: nextState.choiceAt || null,
    onboarding_deferred_at: nextState.deferredAt || null,
  };

  void supabase
    .from('professionals')
    .update(databasePatch)
    .eq('id', userId)
    .then(({ error }) => {
      if (error) console.warn('[Onboarding] Não foi possível persistir a etapa atual:', error.message);
    });

  if (stepChanged) {
    void trackLifecycleEvent('onboarding_step_viewed', {
      metadata: { step: nextState.step, mode: nextState.mode || 'guided' },
      dedupeKey: `onboarding_step_viewed:${userId}:${nextState.step}`,
    });
  }

  return nextState;
};

export const isOnboardingComplete = (userId?: string | null): boolean => {
  const state = getOnboardingState(userId);
  return Boolean(state?.completedAt || state?.step === 'complete' || state?.status === 'completed');
};

export const canAccessApplication = (userId?: string | null): boolean => (
  canAccessApplicationDuringOnboarding(getOnboardingState(userId))
);

export const clearOnboardingState = (userId?: string | null) => {
  if (!userId || typeof window === 'undefined') return;
  window.localStorage.removeItem(getStorageKey(userId));
};

export const completeOnboarding = (userId: string): OnboardingState => {
  const nextState = setOnboardingState(userId, {
    step: 'complete',
    status: 'completed',
    completedAt: new Date().toISOString()
  });

  // Atualiza assincronamente no banco de dados
  supabase
    .from('professionals')
    .update({
      onboarding_completed: true,
      onboarding_status: 'completed',
      onboarding_current_step: 'complete',
    })
    .eq('id', userId)
    .then(({ error }) => {
      if (error) {
        console.error('Erro ao marcar onboarding como completo no banco de dados:', error);
      }
    });

  return nextState;
};

export const hydrateOnboardingFromProfile = (
  userId: string,
  profile: RemoteOnboardingProfile
): OnboardingState => {
  const current = getOnboardingState(userId);
  const hydrated = hydrateOnboardingState(current, profile);
  if (typeof window !== 'undefined') {
    window.localStorage.setItem(getStorageKey(userId), JSON.stringify(hydrated));
  }

  if (
    profile.onboarding_completed !== true
    && profile.onboarding_status === 'not_started'
    && hydrated.status !== 'not_started'
  ) {
    void supabase.from('professionals').update({
      onboarding_status: hydrated.status,
      onboarding_mode: hydrated.mode || null,
      onboarding_current_step: hydrated.step,
      onboarding_choice_at: hydrated.choiceAt || null,
      onboarding_deferred_at: hydrated.deferredAt || null,
    }).eq('id', userId);
  }

  return hydrated;
};

export const chooseOnboardingMode = async (
  userId: string,
  mode: OnboardingMode
): Promise<OnboardingState> => {
  const now = new Date().toISOString();
  const currentStep = getOnboardingState(userId)?.step || 'intro';
  const nextStatus = mode === 'explore' ? 'deferred' : 'in_progress';
  const { data, error } = await supabase.from('professionals').update({
    onboarding_mode: mode,
    onboarding_status: nextStatus,
    onboarding_current_step: currentStep,
    onboarding_choice_at: now,
    onboarding_deferred_at: mode === 'explore' ? now : null,
  }).eq('id', userId).select('id').maybeSingle();
  if (error) throw error;
  if (!data) throw new Error('Não foi possível confirmar a escolha do onboarding.');

  const nextState = setOnboardingState(userId, {
    mode,
    status: nextStatus,
    step: currentStep,
    choiceAt: now,
    deferredAt: mode === 'explore' ? now : undefined,
  });

  await trackLifecycleEvent(mode === 'explore' ? 'onboarding_choice_explore' : 'onboarding_choice_guided', {
    metadata: { mode, step: currentStep },
    dedupeKey: `onboarding_choice:${userId}`,
  });
  return nextState;
};

export const deferOnboarding = async (
  userId: string,
  step?: OnboardingState['step']
): Promise<OnboardingState> => {
  const now = new Date().toISOString();
  const current = getOnboardingState(userId);
  const nextStep = step || current?.step || 'intro';
  const choiceAt = current?.choiceAt || now;
  const { data, error } = await supabase.from('professionals').update({
    onboarding_completed: false,
    onboarding_status: 'deferred',
    onboarding_mode: 'explore',
    onboarding_current_step: nextStep,
    onboarding_choice_at: choiceAt,
    onboarding_deferred_at: now,
  }).eq('id', userId).select('id').maybeSingle();
  if (error) throw error;
  if (!data) throw new Error('Não foi possível adiar o onboarding.');
  const nextState = setOnboardingState(userId, {
    status: 'deferred',
    mode: 'explore',
    step: nextStep,
    deferredAt: now,
    choiceAt,
  });
  return nextState;
};

export const resumeOnboarding = async (
  userId: string,
  patch: Pick<Partial<OnboardingState>, 'step' | 'patientId' | 'patientName'> = {}
): Promise<OnboardingState> => {
  const nextStep = patch.step || getOnboardingState(userId)?.step || 'intro';
  const { data, error } = await supabase.from('professionals').update({
    onboarding_status: 'in_progress',
    onboarding_mode: 'guided',
    onboarding_current_step: nextStep,
    onboarding_deferred_at: null,
  }).eq('id', userId).select('id').maybeSingle();
  if (error) throw error;
  if (!data) throw new Error('Não foi possível retomar o onboarding.');
  const nextState = setOnboardingState(userId, {
    ...patch,
    step: nextStep,
    status: 'in_progress',
    mode: 'guided',
    deferredAt: undefined,
  });
  await trackLifecycleEvent('onboarding_resumed', {
    metadata: { step: nextState.step, mode: 'guided' },
    dedupeKey: `onboarding_resumed:${userId}:${nextState.step}:${new Date().toISOString().slice(0, 10)}`,
  });
  return nextState;
};

export const getOnboardingDestination = (userId?: string | null): string => {
  const state = ensureOnboardingState(userId);

  if (!state) {
    return '/onboarding';
  }
  return getOnboardingDestinationForState(state);
};

src/utils/onboardingState.ts:
export type OnboardingStep = 'intro' | 'patient' | 'evolution' | 'agenda' | 'complete';
export type OnboardingStatus = 'not_started' | 'in_progress' | 'deferred' | 'completed';
export type OnboardingMode = 'guided' | 'explore';

export interface OnboardingState {
  step: OnboardingStep;
  status: OnboardingStatus;
  mode?: OnboardingMode;
  patientId?: string;
  patientName?: string;
  agendaSyncedAt?: string;
  startedAt?: string;
  choiceAt?: string;
  deferredAt?: string;
  updatedAt?: string;
  completedAt?: string;
}

export type RemoteOnboardingProfile = {
  onboarding_completed?: boolean | null;
  onboarding_status?: string | null;
  onboarding_mode?: string | null;
  onboarding_current_step?: string | null;
  onboarding_choice_at?: string | null;
  onboarding_deferred_at?: string | null;
};

export type OnboardingProgressSnapshot = {
  profileReady: boolean;
  patients: Array<{ id: string; google_doc_id: string | null }>;
  evolutionsCount: number;
};

const ONBOARDING_STEPS: readonly OnboardingStep[] = ['intro', 'patient', 'evolution', 'agenda', 'complete'];
const ONBOARDING_STATUSES: readonly OnboardingStatus[] = ['not_started', 'in_progress', 'deferred', 'completed'];
const ONBOARDING_MODES: readonly OnboardingMode[] = ['guided', 'explore'];

export const isOnboardingStep = (value: unknown): value is OnboardingStep => (
  typeof value === 'string' && ONBOARDING_STEPS.includes(value as OnboardingStep)
);

export const isOnboardingStatus = (value: unknown): value is OnboardingStatus => (
  typeof value === 'string' && ONBOARDING_STATUSES.includes(value as OnboardingStatus)
);

export const isOnboardingMode = (value: unknown): value is OnboardingMode => (
  typeof value === 'string' && ONBOARDING_MODES.includes(value as OnboardingMode)
);

export const normalizeOnboardingState = (value: Partial<OnboardingState> | null | undefined): OnboardingState => {
  const step = isOnboardingStep(value?.step) ? value.step : 'intro';
  const inferredStatus: OnboardingStatus = step === 'complete'
    ? 'completed'
    : 'not_started';
  const status = isOnboardingStatus(value?.status) ? value.status : inferredStatus;
  const mode = isOnboardingMode(value?.mode) ? value.mode : undefined;

  return {
    ...value,
    step: status === 'completed' ? 'complete' : step,
    status,
    mode,
  };
};

export const hydrateOnboardingState = (
  localState: Partial<OnboardingState> | null | undefined,
  profile: RemoteOnboardingProfile
): OnboardingState => {
  const local = normalizeOnboardingState(localState);

  if (profile.onboarding_completed === true || profile.onboarding_status === 'completed') {
    return {
      ...local,
      step: 'complete',
      status: 'completed',
      mode: isOnboardingMode(profile.onboarding_mode) ? profile.onboarding_mode : local.mode || 'guided',
    };
  }

  const remoteStatus = isOnboardingStatus(profile.onboarding_status)
    ? profile.onboarding_status
    : null;

  // Preserva progresso local legado quando a migração ainda conhece o usuário
  // apenas como "não iniciado".
  if (
    (!remoteStatus || remoteStatus === 'not_started')
    && (local.status !== 'not_started' || local.step !== 'intro' || Boolean(local.patientId))
  ) {
    return local;
  }

  const remoteStep = isOnboardingStep(profile.onboarding_current_step)
    ? profile.onboarding_current_step
    : local.step;

  return normalizeOnboardingState({
    ...local,
    status: remoteStatus || local.status,
    step: remoteStep,
    mode: isOnboardingMode(profile.onboarding_mode) ? profile.onboarding_mode : local.mode,
    choiceAt: profile.onboarding_choice_at || local.choiceAt,
    deferredAt: profile.onboarding_deferred_at || local.deferredAt,
  });
};

export const canAccessApplicationDuringOnboarding = (state: OnboardingState | null | undefined): boolean => {
  const normalized = normalizeOnboardingState(state);
  return normalized.status === 'deferred' || normalized.status === 'completed';
};

export const isOnboardingChoiceRequired = (state: OnboardingState | null | undefined): boolean => {
  const normalized = normalizeOnboardingState(state);
  return normalized.status === 'not_started' && !normalized.mode;
};

export const getOnboardingDestinationForState = (state: OnboardingState): string => {
  if (state.status === 'deferred' || state.status === 'completed' || state.step === 'complete') {
    return '/painel/dashboard';
  }

  if (state.step === 'patient') {
    return state.patientId
      ? `/painel/patients/${state.patientId}/edit?onboarding=1`
      : '/painel/patients/new?onboarding=1';
  }

  if (state.step === 'evolution' && state.patientId) {
    return `/painel/patients/${state.patientId}/evolutions/new?onboarding=1`;
  }

  if (state.step === 'agenda') {
    return '/onboarding?step=agenda';
  }

  return '/onboarding';
};

export const hasCompletedEssentialOnboardingSteps = (progress: OnboardingProgressSnapshot): boolean => (
  progress.profileReady
  && progress.patients.length > 0
  && progress.patients.some(patient => Boolean(patient.google_doc_id))
  && progress.evolutionsCount > 0
);

export const getNextOnboardingTarget = (
  progress: OnboardingProgressSnapshot
): Pick<OnboardingState, 'step'> & Pick<Partial<OnboardingState>, 'patientId'> => {
  const firstPatient = progress.patients[0];
  const linkedPatient = progress.patients.find(patient => Boolean(patient.google_doc_id));

  if (!progress.profileReady && !firstPatient) {
    return { step: 'intro' };
  }

  if (!firstPatient) {
    return { step: 'patient' };
  }

  if (!linkedPatient) {
    return { step: 'patient', patientId: firstPatient.id };
  }

  if (progress.evolutionsCount === 0) {
    return { step: 'evolution', patientId: linkedPatient.id };
  }

  return { step: 'complete', patientId: linkedPatient.id };
};

export const classifyOnboardingError = (error: unknown, fallback = 'unknown'): string => {
  const message = error instanceof Error ? error.message : String(error || '');
  const normalized = message.toLowerCase();

  if (normalized.includes('insufficient_scopes')) return 'google_insufficient_scopes';
  if (normalized.includes('unauthenticated') || normalized.includes('invalid credentials') || normalized.includes('401')) return 'google_unauthenticated';
  if (normalized.includes('429') || normalized.includes('rate') || normalized.includes('quota')) return 'provider_rate_limited';
  if (normalized.includes('403') || normalized.includes('forbidden')) return 'google_forbidden';
  if (normalized.includes('404') || normalized.includes('file not found')) return 'google_resource_not_found';
  if (normalized.includes('network') || normalized.includes('failed to fetch') || normalized.includes('offline')) return 'network_unavailable';
  return fallback;
};

