export const generateReportPDF = (
  rep: any,
  pat: any,
  prof: any,
  siteConfig: any,
  logoBase64?: string | null
) => {
  const doc = new jsPDF({
    orientation: 'portrait',
    unit: 'mm',
    format: 'a4'
  });

  const pageWidth = doc.internal.pageSize.getWidth();
  const margin = 20; // 2cm Margem Esquerda
  const contentWidth = pageWidth - (2 * margin); // 2cm Margem Direita (20mm)

  const primaryRgb = hexToRgb(siteConfig?.colors?.primary || '#005C13') || { r: 0, g: 92, b: 19 };

  // Cabecalho Timbrado
  let taglineX = margin;
  const appName = siteConfig?.pwa_app_name || "Evolução Clínica";

  if (logoBase64) {
    try {
      taglineX = drawDocumentLogo(doc, logoBase64, prof?.custom_logo_settings, margin, 7);
    } catch (err) {
      console.error("Error drawing logo in PDF:", err);
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(18);
      doc.setTextColor(primaryRgb.r, primaryRgb.g, primaryRgb.b);
      doc.text(appName, margin, 20);
    }

  } else {
    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(18);
    doc.setTextColor(primaryRgb.r, primaryRgb.g, primaryRgb.b);
    doc.text(appName, margin, 20);

    const appNameWidth = doc.getTextWidth(appName);

    // Linha divisória vertical
    doc.setDrawColor(200, 195, 190); // stone-300
    doc.setLineWidth(0.25);
    doc.line(margin + appNameWidth + 5, 11, margin + appNameWidth + 5, 25);

    taglineX = margin + appNameWidth + 9;
  }

  // Tagline na mesma linha com tipografia Outfit/Helvetica Bold 11, e subtexto abaixo
  doc.setFont('Helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(28, 25, 22); // text-stone-800
  doc.text("Plataforma Inteligente de Acompanhamento Terapêutico", taglineX, 16);

  doc.setFont('Helvetica', 'normal');
  doc.setFontSize(7.5);
  doc.setTextColor(120, 113, 108); // text-stone-500
  doc.text("Emitido por evolucaoclinica.app.br", taglineX, 21);

  doc.setDrawColor(primaryRgb.r, primaryRgb.g, primaryRgb.b);
  doc.setLineWidth(0.5);
  doc.line(margin, 28, pageWidth - 20, 28);

  // Identificação do Documento
  doc.setFontSize(12);
  doc.setFont('Helvetica', 'bold');
  doc.setTextColor(primaryRgb.r, primaryRgb.g, primaryRgb.b);
  const docTitle = rep.type === 'evolution_report' ? 'Relatório de Evolução Clínico' : 'Plano de Desenvolvimento Individual (PDI)';
  doc.text(docTitle, margin, 38);

  // Tabela de Dados
  doc.setFontSize(9);
  doc.setFont('Helvetica', 'normal');
  doc.setTextColor(28, 25, 22); // text-color

  let y = 46;
  doc.text(`Paciente: ${pat?.full_name || 'Não informado'}`, margin, y);
  doc.text(`Profissional: ${prof?.full_name || 'Não informado'}`, margin + contentWidth / 2, y);

  y += 6;
  if (prof?.professional_register) {
    doc.text(`Registro Profissional: ${prof.professional_register}`, margin, y);
  }
  const isPdi = rep.type !== 'evolution_report';
  const rightSecondaryLabel = isPdi
    ? `Data do Plano: ${new Date(rep.created_at || Date.now()).toLocaleDateString('pt-BR')}`
    : `Período de Análise: ${rep.period_label || 'Não informado'}`;
  doc.text(rightSecondaryLabel, margin + contentWidth / 2, y);

  if (isPdi) {
    y += 6;
    if (prof?.professional_title) {
      doc.text(`Especialidade: ${prof.professional_title}`, margin, y);
    }
    doc.text(`Período de Análise: ${rep.period_label || 'Não informado'}`, margin + contentWidth / 2, y);
  }

  y += 8;
  doc.setDrawColor(231, 229, 228);
  doc.setLineWidth(0.2);
  doc.line(margin, y, pageWidth - 20, y);

  // Conteúdo do Relatório
  y += 10;

  // Dividir o conteudo em linhas de markdown
  const lines = getReportBodyContent(rep.content).split('\n');

  for (const line of lines) {
    if (y > 270) {
      doc.addPage();
      y = 20; // reset y
    }

    const trimmed = line.trim();
    if (!trimmed) {
      y += 4; // espaco em branco
      continue;
    }

    if (trimmed.startsWith('# ')) {
      y += 4;
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(14);
      doc.setTextColor(primaryRgb.r, primaryRgb.g, primaryRgb.b);
      doc.text(trimmed.substring(2), margin, y);
      y += 8;
    } else if (trimmed.startsWith('## ')) {
      y += 3;
      doc.setFont('Helvetica', 'bold');
      doc.setFontSize(11);
      doc.setTextColor(primaryRgb.r, primaryRgb.g, primaryRgb.b);
      doc.text(trimmed.substring(3), margin, y);
      y += 6;
    } else if (trimmed.startsWith('---')) {
      y += 2;
      doc.setDrawColor(231, 229, 228);
      doc.line(margin, y, pageWidth - 20, y);
      y += 4;
    } else if (trimmed.startsWith('- ') || trimmed.startsWith('* ')) {
      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(10);
      doc.setTextColor(28, 25, 22);

      const text = trimmed.substring(2).replace(/\*\*([^*]+)\*\*/g, '$1');
      const splitText = doc.splitTextToSize(text, contentWidth - 6);

      for (let i = 0; i < splitText.length; i++) {
        if (y > 270) {
          doc.addPage();
          y = 20;
        }
        if (i === 0) {
          doc.text("•", margin, y);
          doc.text(splitText[i], margin + 5, y);
        } else {
          doc.text(splitText[i], margin + 5, y);
        }
        y += 5.5;
      }
      y += 1.5;
    } else {
      doc.setFont('Helvetica', 'normal');
      doc.setFontSize(10);
      doc.setTextColor(28, 25, 22);

      const text = trimmed.replace(/\*\*([^*]+)\*\*/g, '$1');
      const splitText = doc.splitTextToSize(text, contentWidth);

      for (let i = 0; i < splitText.length; i++) {
        if (y > 270) {
          doc.addPage();
          y = 20;
        }
        doc.text(splitText[i], margin, y);
        y += 5.5;
      }
      y += 2;
    }
  }

  // Carimbo de Assinatura se estiver assinado
  if (rep.status === 'signed') {
    y += 12;
    if (y > 230) {
      doc.addPage();
      y = 30;
    }

    // Caixa de Assinatura
    doc.setFillColor(240, 253, 244); // bg-emerald-50
    doc.setDrawColor(167, 243, 208); // border-emerald-200
    doc.setLineWidth(0.3);
    doc.rect(margin, y, contentWidth, 38, 'FD');

    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(4, 120, 87); // text-emerald-700
    doc.text("DOCUMENTO ASSINADO DIGITALMENTE VIA CHAVE DO APLICATIVO", margin + 5, y + 6);

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(55, 65, 81);
    doc.text(`Assinado por: ${rep.signed_by_name} (${rep.signed_by_register})`, margin + 5, y + 14);

    const formattedDate = new Date(rep.signature_date).toLocaleString('pt-BR');
    doc.text(`Data/Hora: ${formattedDate}`, margin + 5, y + 20);
    doc.text(`IP de Origem: ${rep.signature_ip}   |   Algoritmo: SHA-256`, margin + 5, y + 26);

    doc.setFont('Courier', 'normal');
    doc.setFontSize(7);
    doc.text(`Hash: ${rep.signature_hash}`, margin + 5, y + 32);
  } else {
    // Rodapé normal de assinatura manual
    y += 20;
    if (y > 250) {
      doc.addPage();
      y = 30;
    }
    doc.setDrawColor(87, 83, 78);
    doc.setLineWidth(0.3);
    doc.line(pageWidth / 2 - 30, y, pageWidth / 2 + 30, y);

    doc.setFont('Helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(28, 25, 22);
    doc.text(prof?.full_name || 'Profissional de Saúde', pageWidth / 2, y + 5, { align: 'center' });
    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(8);
    doc.text(prof?.professional_register || '', pageWidth / 2, y + 9, { align: 'center' });
  }

  // Rodapé de Assinatura Corrente em Todas as Páginas
  const totalPages = doc.getNumberOfPages();
  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);

    // Desenhar uma linha sutil acima do rodape
    doc.setDrawColor(231, 229, 228);
    doc.setLineWidth(0.2);
    doc.line(margin, 281, pageWidth - 20, 281);

    doc.setFont('Helvetica', 'normal');
    doc.setFontSize(7);
    doc.setTextColor(120, 113, 108); // text-stone-500

    const pageText = `Página ${i} de ${totalPages}`;

    if (rep.status === 'signed') {
      const shortHash = rep.signature_hash ? `${rep.signature_hash.substring(0, 16)}...` : '';
      const formattedDate = new Date(rep.signature_date).toLocaleDateString('pt-BR');

      // Linha 1: Dados do profissional
      const line1 = `Assinado Digitalmente por: ${rep.signed_by_name} (${rep.signed_by_register})`;
      doc.text(line1, margin, 285);

      // Linha 2: Data, Hash e Página
      const line2 = `Data: ${formattedDate} | Hash: ${shortHash}`;
      doc.text(line2, margin, 289);

      doc.text(pageText, pageWidth - 20 - doc.getTextWidth(pageText), 289);
    } else {
      const line1 = `Rascunho de Documento - Não possui validade jurídica antes de ser assinado`;
      doc.text(line1, margin, 285);
      doc.text(pageText, pageWidth - 20 - doc.getTextWidth(pageText), 289);
    }
  }

  return doc;
};

src/utils/richText.ts:
const escapeHtml = (value: string) => value
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

export type RichTextStyleRange = {
  start: number;
  end: number;
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
};

const inlineMarkdownToHtml = (value: string) => escapeHtml(value)
  .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
  .replace(/<u>(.*?)<\/u>/g, '<u>$1</u>')
  .replace(/(?<!\*)\*([^*]+)\*(?!\*)/g, '<em>$1</em>');

export const markdownToRichHtml = (markdown: string) => {
  if (!markdown) return '<p><br></p>';

  return markdown.split('\n').map((line) => {
    if (/^###\s+/.test(line)) return `<h3>${inlineMarkdownToHtml(line.replace(/^###\s+/, ''))}</h3>`;
    if (/^##\s+/.test(line)) return `<h2>${inlineMarkdownToHtml(line.replace(/^##\s+/, ''))}</h2>`;
    if (/^#\s+/.test(line)) return `<h1>${inlineMarkdownToHtml(line.replace(/^#\s+/, ''))}</h1>`;
    if (/^-\s+/.test(line)) return `<div data-list="bullet">• ${inlineMarkdownToHtml(line.replace(/^-\s+/, ''))}</div>`;
    if (/^\d+\.\s+/.test(line)) return `<div data-list="ordered">${inlineMarkdownToHtml(line)}</div>`;
    return `<p>${inlineMarkdownToHtml(line) || '<br>'}</p>`;
  }).join('');
};

const nodeToMarkdown = (node: Node): string => {
  if (node.nodeType === Node.TEXT_NODE) return node.textContent || '';
  if (node.nodeType !== Node.ELEMENT_NODE) return '';

  const element = node as HTMLElement;
  const content = Array.from(element.childNodes).map(nodeToMarkdown).join('');
  switch (element.tagName) {
    case 'STRONG': case 'B': return `**${content}**`;
    case 'EM': case 'I': return `*${content}*`;
    case 'U': return `<u>${content}</u>`;
    case 'BR': return '\n';
    case 'H1': return `# ${content}\n`;
    case 'H2': return `## ${content}\n`;
    case 'H3': return `### ${content}\n`;
    case 'LI': return `- ${content}\n`;
    case 'P': case 'DIV': return `${content}\n`;
    default: return content;
  }
};

export const richHtmlToMarkdown = (html: string) => {
  const container = document.createElement('div');
  container.innerHTML = html;
  return Array.from(container.childNodes).map(nodeToMarkdown).join('')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+\n/g, '\n')
    .trim();
};

export const markdownToGoogleDocsText = (markdown: string): { text: string; styles: RichTextStyleRange[] } => {
  let text = '';
  const styles: RichTextStyleRange[] = [];
  const stack: Array<{ marker: string; start: number; style: Omit<RichTextStyleRange, 'start' | 'end'> }> = [];
  const tokens = /\*\*|(?<!\*)\*(?!\*)|<u>|<\/u>/g;
  let lastIndex = 0;
  let match: RegExpExecArray | null;

  const append = (value: string) => { text += value; };
  while ((match = tokens.exec(markdown))) {
    append(markdown.slice(lastIndex, match.index));
    const marker = match[0];
    const existingIndex = stack.map((item) => item.marker).lastIndexOf(marker === '</u>' ? '<u>' : marker);
    if (existingIndex >= 0) {
      const opened = stack.splice(existingIndex, 1)[0];
      if (text.length > opened.start) styles.push({ start: opened.start, end: text.length, ...opened.style });
    } else if (marker === '**') {
      stack.push({ marker, start: text.length, style: { bold: true } });
    } else if (marker === '*') {
      stack.push({ marker, start: text.length, style: { italic: true } });
    } else if (marker === '<u>') {
      stack.push({ marker, start: text.length, style: { underline: true } });
    } else {
      append(marker);
    }
    lastIndex = tokens.lastIndex;
  }
  append(markdown.slice(lastIndex));
  for (const opened of stack) append(opened.marker);
  return { text, styles };
};

export const textRunToMarkdown = (content: string, style: any = {}) => {
  const value = content || '';
  let result = value;
  if (style.underline) result = `<u>${result}</u>`;
  if (style.italic) result = `*${result}*`;
  if (style.bold) result = `**${result}**`;
  return result;
};

src/utils/subscriptionAccess.ts:
type SubscriptionAccessInput = {
  profileRole?: string | null;
  subscriptionPlan?: string | null;
  subscriptionStatus?: string | null;
  subscriptionEndsAt?: string | null;
};

function hasNotExpired(subscriptionEndsAt?: string | null) {
  if (!subscriptionEndsAt) return true;
  const timestamp = Date.parse(subscriptionEndsAt);
  return Number.isNaN(timestamp) || timestamp >= Date.now();
}

export function hasActivePaidAccess(input: SubscriptionAccessInput) {
  if (input.profileRole === 'admin' || input.subscriptionPlan === 'none') return true;

  return (
    (input.subscriptionPlan === 'monthly' || input.subscriptionPlan === 'yearly' || input.subscriptionPlan === 'courtesy') &&
    (input.subscriptionStatus === 'active' || input.subscriptionStatus === 'trialing') &&
    hasNotExpired(input.subscriptionEndsAt)
  );
}

export function hasActiveYearlyAccess(input: SubscriptionAccessInput) {
  if (input.profileRole === 'admin' || input.subscriptionPlan === 'none') return true;

  return (
    (input.subscriptionPlan === 'yearly' || input.subscriptionPlan === 'courtesy') &&
    (input.subscriptionStatus === 'active' || input.subscriptionStatus === 'trialing') &&
    hasNotExpired(input.subscriptionEndsAt)
  );
}

src/utils/subscriptionPlans.ts:
export type SubscriptionPlan = 'trial' | 'monthly' | 'yearly' | 'courtesy' | 'none';
export type SubscriptionStatus = 'trialing' | 'active' | 'past_due' | 'canceled' | 'unpaid';
export type ProfessionalAccountStatus = 'active' | 'pending' | 'inactive';

type ManagedSubscriptionInput = {
  subscriptionPlan: SubscriptionPlan;
  subscriptionStatus: SubscriptionStatus;
  subscriptionEndsAt: string | null;
  accountStatus: ProfessionalAccountStatus;
};

export function normalizeManagedSubscription(input: ManagedSubscriptionInput): ManagedSubscriptionInput {
  if (input.subscriptionPlan !== 'courtesy') return input;

  return {
    ...input,
    subscriptionStatus: 'active',
    subscriptionEndsAt: null,
    accountStatus: 'active'
  };
}

export function isPaidSubscriberForMetrics(input: {
  subscription_plan?: string | null;
  subscription_status?: string | null;
  status?: string | null;
}) {
  return (
    (input.subscription_plan === 'monthly' || input.subscription_plan === 'yearly') &&
    input.subscription_status === 'active' &&
    input.status === 'active'
  );
}

export function getSubscriptionPlanLabel(plan?: string | null) {
  switch (plan) {
    case 'monthly': return 'Plano Mensal';
    case 'yearly': return 'Plano Anual';
    case 'courtesy': return 'Plano Cortesia';
    case 'trial': return 'Teste (Trial)';
    case 'none': return 'Vitalício';
    default: return 'Sem Plano';
  }
}

src/utils/supabaseFunctionErrors.ts:
type FunctionErrorContext = {
  json?: () => Promise<unknown>;
  text?: () => Promise<string>;
};

function getFallbackMessage(error: unknown, fallback: string) {
  if (error instanceof Error && error.message) {
    return error.message;
  }

  if (typeof error === 'string' && error.trim()) {
    return error;
  }

  return fallback;
}

export async function resolveSupabaseFunctionErrorMessage(error: unknown, fallback: string) {
  const context = (error as { context?: FunctionErrorContext } | null)?.context;

  if (!context) {
    return getFallbackMessage(error, fallback);
  }

  try {
    const payload = await context.json?.();
    if (payload && typeof payload === 'object') {
      const data = payload as { error?: unknown; message?: unknown };
      if (typeof data.error === 'string' && data.error.trim()) {
        return data.error;
      }
      if (typeof data.message === 'string' && data.message.trim()) {
        return data.message;
      }
    }
  } catch {
    // Ignore JSON parsing failures and try text fallback.
  }

  try {
    const rawText = await context.text?.();
    if (rawText?.trim()) {
      try {
        const parsed = JSON.parse(rawText) as { error?: unknown; message?: unknown };
        if (typeof parsed.error === 'string' && parsed.error.trim()) {
          return parsed.error;
        }
        if (typeof parsed.message === 'string' && parsed.message.trim()) {
          return parsed.message;
        }
      } catch {
        return rawText;
      }
    }
  } catch {
    // Ignore text parsing failures and return the original error message.
  }

  return getFallbackMessage(error, fallback);
}
